ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    subscribers: {
        subscriber_particulars: {
            subscriber_data: {
                action: "modify",
                user: vars.initialPayload.UpdateAccountDataSystemsBody.User,
                subscriber_id: vars.initialPayload.UpdateAccountDataSystemsBody.SubscriberId,
                first_name: vars.initialPayload.UpdateAccountDataSystemsBody.FirstName,
                last_name: vars.initialPayload.UpdateAccountDataSystemsBody.LastName,
                subscriber_name: vars.initialPayload.UpdateAccountDataSystemsBody.SubscriberName
            },
            billing_address_data:{
                action: "modify",
                bill_address1: vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress,
                bill_city: vars.initialPayload.UpdateAccountDataSystemsBody.AddressGeoCode,
                bill_country_code: "COL",
                bill_state_code: vars.initialPayload.UpdateAccountDataSystemsBody.BillStateCode
            },
            address_data:{
                action: "modify",
                address1: vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress,
                address_geo_code: vars.initialPayload.UpdateAccountDataSystemsBody.AddressGeoCode,
                city: vars.initialPayload.UpdateAccountDataSystemsBody.City,
                country_code: "COL",
                state_code: vars.initialPayload.UpdateAccountDataSystemsBody.BillStateCode
            },
            email_data:{
                action: "add",
                email_address: vars.initialPayload.UpdateAccountDataSystemsBody.EmailAddress,
                email_is_primary_flag: vars.initialPayload.UpdateAccountDataSystemsBody.EmailIsPrimaryFlag
            },
            invoice_method_data:{
                action: "modify",
                invoice_method_name: "Cuentas LTE Detallada",
                invoice_delivery_name: vars.initialPayload.UpdateAccountDataSystemsBody.InvoiceDeliveryType
            }
        }
    }
}

%dw 2.0
output application/json
---
{
	ResponseData: {
		UpdateAccountDataRVCResponse: vars.responseRVC,
		UpdateAccountDataRMCAResponse: {
			Code: "NOK",
			Description: "Error RVC"
		},
		UpdateAccountDataMDMResponse: {
			Code: "NOK",
			Description: "Error RVC"
		}
	}
}

%dw 2.0
output application/json
---
{
	ZRFC_BP_UPDATE_DATA:{
	    COUNTRY: "CO",
	    CTA_REVCHAIN: vars.initialPayload.UpdateAccountDataSystemsBody.SubscriberId,
	    E_MAIL: vars.initialPayload.UpdateAccountDataSystemsBody.EmailAddress,
	    FIRSTNAME: if(isEmpty(vars.initialPayload.UpdateAccountDataSystemsBody.FirstName)) 
	    vars.initialPayload.UpdateAccountDataSystemsBody.SubscriberName 
	    else vars.initialPayload.UpdateAccountDataSystemsBody.FirstName,
	    LASTNAME: vars.initialPayload.UpdateAccountDataSystemsBody.LastName,
	    RETURN: {},
	    STREET: vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress
	    }
	}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	Item: payload.ZRFC_BP_UPDATE_DATAResponse.Item map ((item, index) -> 
	{
	    Code: item.TYPE,
	    Description: item.MESSAGE
    })
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    ActualizarDatosCuentaFacturacion:{
        cuentaFactuarcion: vars.initialPayload.UpdateAccountDataSystemsBody.SubscriberId,
        correo: if(isEmpty(vars.initialPayload.UpdateAccountDataSystemsBody.EmailAddress)) null 
        else vars.initialPayload.UpdateAccountDataSystemsBody.EmailAddress,
        direccion: if(isEmpty(vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress)) null 
        else vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress,
        tipoEnvio: if(vars.initialPayload.UpdateAccountDataSystemsBody.InvoiceDeliveryType == "Email") "Electronica" 
        else if(isEmpty(vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress)) null 
        else vars.initialPayload.UpdateAccountDataSystemsBody.BillAddress,
        usuario: if(isEmpty(vars.initialPayload.UpdateAccountDataSystemsBody.User)) null 
        else vars.initialPayload.UpdateAccountDataSystemsBody.User
    }
}

%dw 2.0
output application/json
---
{
	ResponseData: {
		UpdateAccountDataRVCResponse: vars.responseRVC,
		(UpdateAccountDataRMCAResponse: vars.responseRMCA) if(vars.responseRMCA != null),
		(UpdateAccountDataMDMResponse: vars.responseMDM) if(vars.responseMDM != null)
		}
}
